import{_ as a}from"./chunks/daily-2026-08-18-files-first-shared-ledger._Oq6pvn-.js";import{_ as n,C as i,o as s,c as r,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Why Multi-Agent Governance Can Start with Files","description":"","frontmatter":{"title":"Why Multi-Agent Governance Can Start with Files","date":"2026-08-18","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"Why are files, paths, and events a useful starting point for local-first multi-agent governance, and what do they explicitly not guarantee?","summary":"Files are not bargain-bin replacements for queues or workflow engines. Their first value is to establish a work ledger that humans and agents can inspect before infrastructure is upgraded in response to measured pressure.","item_id":"MANUAL-20260818-FILES","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-files-first-multi-agent-governance-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-fact-matrices.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-independent-editorial-review.md"]},"headers":[],"relativePath":"en/engineering/2026-08-18-files-first-multi-agent-governance.md","filePath":"en/engineering/2026-08-18-files-first-multi-agent-governance.md","lastUpdated":1787065994000}'),c={name:"en/engineering/2026-08-18-files-first-multi-agent-governance.md"};function d(h,e,p,u,g,m){const t=i("ArticleCover");return s(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-18-files-first-multi-agent-governance-cover.webp",kicker:"Open-source Engineering · Research Article",title:"Why Multi-Agent Governance Can Start with Files",summary:"Files are not a cheap substitute for a queue or workflow engine. Their first governance value is a shared working ledger that humans and agents can inspect directly, with infrastructure upgraded only when real pressure demands it.",version:"MANUAL-20260818-FILES",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/zh/engineering/2026-08-18-files-first-multi-agent-governance",languageLabel:"中文"}),e[0]||(e[0]=l('<h1 id="why-multi-agent-governance-can-start-with-files" tabindex="-1">Why Multi-Agent Governance Can Start with Files <a class="header-anchor" href="#why-multi-agent-governance-can-start-with-files" aria-label="Permalink to &quot;Why Multi-Agent Governance Can Start with Files&quot;">​</a></h1><blockquote><p>Files are not a bargain-bin substitute for queues, databases, or workflow engines. Their first governance value is simpler: they can create a work ledger that both humans and agents can read, inspect, copy, and recover.</p></blockquote><p><strong>Series map:</strong> this article explains why files are a useful starting point. Continue with <a href="/joinwell52/en/engineering/2026-08-18-fcop-file-state-machine">the state-machine implementation</a>, then <a href="/joinwell52/en/digital-employee/2026-08-18-cursor-ai-development-team">the Cursor operating guide</a>. The three pieces cover governance value, protocol mechanics, and accepted delivery.</p><p>Imagine four agents working in four conversations. One changes code, one writes tests, one checks the runtime, and one reviews the result. Two hours later, every window says “done,” yet the person in charge still cannot answer basic questions. Which task version was authoritative? Who changed the scope? Which test report belongs to which implementation? Did the reason for rejection make it into the rework request?</p><p>The missing component is not a smarter model. It is shared operational truth.</p><p>For a local-first, single-machine agent system with low or moderate concurrency, that truth can begin as files. Tasks, reports, issues, and review decisions become explicit artifacts. Directory location represents current lifecycle state. Append-only events preserve how the state changed. FCoP summarizes the model as: <strong>files carry the protocol, paths address state, and events record history.</strong></p><p>This is not an argument that files should replace every other system. It is an ordering principle: make the work visible and inspectable before adding a more elaborate control plane.</p><h2 id="what-the-unix-lesson-actually-says" tabindex="-1">What the Unix lesson actually says <a class="header-anchor" href="#what-the-unix-lesson-actually-says" aria-label="Permalink to &quot;What the Unix lesson actually says&quot;">​</a></h2><p>The useful lesson in Ritchie and Thompson’s <a href="https://pdos.csail.mit.edu/6.828/2014/readings/ritchie78unix.pdf" target="_blank" rel="noreferrer">The UNIX Time-Sharing System</a> is more precise than the slogan “everything is a file.” Unix organized objects in a hierarchical namespace, made ordinary files, devices, and inter-process I/O accessible through largely compatible interfaces, and enabled small programs to compose through standard input, output, and pipes.</p><p>Three design ideas transfer well to agent governance.</p><p>First, a common interface reduces integration cost. A human can open a task in an editor, an agent can parse its front matter, a CLI can scan the directory, and a web view can index it. They do not need the same SDK to understand the work.</p><p>Second, names and locations can carry stable meaning. Directories such as <code>inbox/</code>, <code>active/</code>, <code>review/</code>, and <code>done/</code> form a state surface that programs and people can both inspect.</p><p>Third, complicated behavior can be split into small, composable tools. Creation, validation, transition, review, and archival can evolve independently if they honor the same artifact contract.</p><p>The original paper also prevents an overclaim. Unix still needed processes, pipes, permissions, and internal interlocks. Concurrent writes could corrupt file content. In this article, “everything is a file” therefore means <strong>externalize coordination facts through open, readable artifacts where practical</strong>. It does not mean that the filesystem automatically solves concurrency, durability, or distributed consistency.</p><h2 id="files-as-a-practical-blackboard" tabindex="-1">Files as a practical blackboard <a class="header-anchor" href="#files-as-a-practical-blackboard" aria-label="Permalink to &quot;Files as a practical blackboard&quot;">​</a></h2><p>H. Penny Nii’s classic article on <a href="https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/537" target="_blank" rel="noreferrer">the blackboard model</a> describes systems in which multiple knowledge sources contribute intermediate results to a shared problem-solving structure. No individual knowledge source has to keep the entire truth in private memory; coordination happens through a common work surface.</p><p>A directory can implement such a surface, but a directory is not automatically a blackboard. It becomes useful for governance only when:</p><ol><li>every artifact has a defined identity;</li><li>the current state has one authoritative location;</li><li>transitions leave ordered evidence;</li><li>roles have explicit permissions and responsibilities; and</li><li>completion depends on verifiable evidence, not an agent’s assertion.</li></ol><p>That distinction separates a chat archive from a work ledger. Chat is organized by who spoke when. A work ledger is organized by the work object, its owner, its evidence, and its decisions.</p><p><img src="'+a+`" alt="Multiple roles write to one file, path, and event fact surface that humans, agents, and tools can inspect"></p><p><em>Figure 1. File-based governance first creates a shared fact surface. It coordinates tasks, state, and evidence; it does not replace execution or distributed consistency. Source: Research Center synthesis of Unix, FCoP, and TMPA materials.</em></p><h2 id="four-facts-a-minimal-ledger-should-preserve" tabindex="-1">Four facts a minimal ledger should preserve <a class="header-anchor" href="#four-facts-a-minimal-ledger-should-preserve" aria-label="Permalink to &quot;Four facts a minimal ledger should preserve&quot;">​</a></h2><p>FCoP uses four IPC envelopes to keep different claims separate:</p><table tabindex="0"><thead><tr><th>Artifact</th><th>Question it answers</th><th>Minimum useful content</th></tr></thead><tbody><tr><td><code>TASK</code></td><td>Who is expected to deliver what?</td><td>sender, recipient, priority, parent, scope, acceptance criteria</td></tr><tr><td><code>REPORT</code></td><td>What did the worker actually do?</td><td>task reference, changes, tests, evidence paths, remaining risks</td></tr><tr><td><code>ISSUE</code></td><td>What is blocking the work?</td><td>symptom, impact, attempted actions, required decision</td></tr><tr><td><code>REVIEW</code></td><td>Who made what judgment on which evidence?</td><td>subject, reviewer, verdict, rationale, next action</td></tr></tbody></table><h2 id="five-lifecycle-buckets-use-location-to-answer-where-is-the-task-now" tabindex="-1">Five lifecycle buckets: use location to answer “where is the task now?” <a class="header-anchor" href="#five-lifecycle-buckets-use-location-to-answer-where-is-the-task-now" aria-label="Permalink to &quot;Five lifecycle buckets: use location to answer “where is the task now?”&quot;">​</a></h2><p>The five directories under <code>_lifecycle/</code> form a minimal observable state machine: <strong>a TASK may occupy only one bucket at a time; moving the file is the state transition.</strong></p><table tabindex="0"><thead><tr><th>Lifecycle bucket</th><th>Question it answers</th><th>Typical action</th></tr></thead><tbody><tr><td><code>inbox/</code></td><td>A new task exists. Who will claim it?</td><td>create, then wait for <code>claim</code></td></tr><tr><td><code>active/</code></td><td>Who is executing or reworking it?</td><td>claim; rejected work returns here</td></tr><tr><td><code>review/</code></td><td>Delivery was submitted. Who will decide?</td><td><code>submit</code>, then approve or reject</td></tr><tr><td><code>done/</code></td><td>Did the protocol lifecycle finish or receive approval?</td><td><code>finish</code> or <code>approve</code>; this is not yet business acceptance</td></tr><tr><td><code>archive/</code></td><td>Has the work left the active collaboration surface?</td><td>archive after upstream acceptance</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox --claim--&gt; active --submit--&gt; review --approve--&gt; done --archive--&gt; archive</span></span>
<span class="line"><span>                    |   ^                   |</span></span>
<span class="line"><span>                    |   +------reject-------+</span></span>
<span class="line"><span>                    +---------finish-------&gt;+</span></span></code></pre></div><p>Four rules keep this model unambiguous:</p><ol><li><strong>One current location:</strong> the same TASK cannot exist in both <code>active</code> and <code>done</code>.</li><li><strong>Move, do not relabel:</strong> state changes through controlled migration, not an Agent editing a mutable status field.</li><li><strong>Separate now from history:</strong> the path answers “where is it now”; append-only <code>transitions:</code> records how it arrived there.</li><li><strong>Separate state from credentials:</strong> REPORT, ISSUE and REVIEW are delivery, blocking and governance evidence, not current task state.</li></ol><p>FCoP v2&#39;s <code>tasks / reports / issues / shared / log</code> were the old five buckets organized by <strong>artifact type</strong>. FCoP v3&#39;s <code>_lifecycle/</code> buckets organize TASK files by <strong>work stage</strong>. They are different concepts.</p><p>Likewise, <code>_lifecycle/review/</code> means a TASK awaits a decision, while <code>reviews/REVIEW-*.md</code> is an independent governance judgment.</p><p>The resulting ledger has three distinct layers:</p><ul><li>artifact content explains what the work is, what happened, and what evidence supports it;</li><li>path identifies the TASK&#39;s current lifecycle stage;</li><li><code>transitions:</code> records how it arrived there.</li></ul><blockquote><p><strong>For current lifecycle position, the path is the authoritative NOW fact. For business completion, the upstream role&#39;s acceptance of the REPORT and its evidence is decisive.</strong></p></blockquote><p>This distinction keeps a worker&#39;s completion claim, protocol approval, and upstream acceptance from collapsing into one ambiguous <code>done</code> label.</p><h2 id="inspectability-changes-the-quality-of-rework" tabindex="-1">Inspectability changes the quality of rework <a class="header-anchor" href="#inspectability-changes-the-quality-of-rework" aria-label="Permalink to &quot;Inspectability changes the quality of rework&quot;">​</a></h2><p>The FCoP repository contains a small <a href="https://github.com/joinwell52-AI/FCoP/tree/a859e6747fe6e5e2d686e0114c77774726d7f748/docs/tutorials/assets/tetris-en/evidence" target="_blank" rel="noreferrer">Tetris dogfood evidence set</a>. In one trace, a task was underspecified. The implementer guessed instead of using the available issue path, and the defect appeared in the guessed area. The review rejected the result, and an administrator produced a sharper rework task.</p><p>One example cannot establish a defect-rate improvement or prove production-scale performance. It supports a narrower conclusion: when task, report, review, and rework artifacts remain separate, a failure does not collapse into a vague memory. A maintainer can locate where ambiguity entered, whether the worker escalated it, and whether the review became an actionable next task.</p><p>The ledger does not eliminate mistakes. It makes them attributable, discussable, and convertible into the next decision.</p><h2 id="when-starting-with-files-is-sensible" tabindex="-1">When starting with files is sensible <a class="header-anchor" href="#when-starting-with-files-is-sensible" aria-label="Permalink to &quot;When starting with files is sensible&quot;">​</a></h2><p>A file-backed ledger is a strong starting point when:</p><ul><li>work happens on one machine or in a clearly bounded shared workspace;</li><li>human readability matters more than millisecond latency;</li><li>artifacts should fit Git, backups, and ordinary file tools;</li><li>people need to inspect and approve agent work directly; and</li><li>the protocol is still evolving faster than a control-plane implementation.</li></ul><p>Pressure to add a stronger runtime or index appears when:</p><ul><li>many machines compete for the same tasks;</li><li>the system requires strict transactions, granular authorization, or complex queries;</li><li>retries, leases, timeouts, and throughput guarantees become central;</li><li>network-filesystem semantics are not good enough; or</li><li>directory scans and manual discovery become operational bottlenecks.</li></ul><p>The useful separation is between an <strong>artifact plane</strong>, which preserves readable evidence, and an <strong>execution plane</strong>, which owns scheduling, isolation, retries, and scale. They can begin in one local directory and later evolve into distinct components.</p><h2 id="a-minimum-structure-you-can-build-today" tabindex="-1">A minimum structure you can build today <a class="header-anchor" href="#a-minimum-structure-you-can-build-today" aria-label="Permalink to &quot;A minimum structure you can build today&quot;">​</a></h2><p>For an article about FCoP v3, the useful minimum is the protocol&#39;s actual structure rather than a separate <code>events/</code> directory that could be mistaken for another authority:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>  fcop/</span></span>
<span class="line"><span>    fcop.json</span></span>
<span class="line"><span>    _lifecycle/</span></span>
<span class="line"><span>      inbox/</span></span>
<span class="line"><span>      active/</span></span>
<span class="line"><span>      review/</span></span>
<span class="line"><span>      done/</span></span>
<span class="line"><span>      archive/</span></span>
<span class="line"><span>    reports/</span></span>
<span class="line"><span>    issues/</span></span>
<span class="line"><span>    shared/</span></span>
<span class="line"><span>    reviews/</span></span>
<span class="line"><span>    history/</span></span>
<span class="line"><span>      YYYY-MM-DD/</span></span>
<span class="line"><span>  workspace/</span></span>
<span class="line"><span>    &lt;slug&gt;/</span></span></code></pre></div><p>This structure contains three different planes:</p><ul><li><code>_lifecycle/</code> is the <strong>current TASK state plane</strong>;</li><li><code>reports/</code>, <code>issues/</code>, and <code>reviews/</code> form the <strong>evidence and governance plane</strong> and do not move with TASK state;</li><li><code>history/</code> is the <strong>long-term history plane</strong> for closed tasks and paired reports.</li></ul><p>Each TASK keeps append-only migration history in <code>transitions:</code>. A separate <code>events/</code> directory would create another truth that could drift from the TASK file.</p><p>Then ask seven questions:</p><ol><li>Does each unit of work have a unique identity and recipient?</li><li>Can a human find the authoritative version in under a minute?</li><li>Does “done” point to tests, a diff, or other environmental evidence?</li><li>Is the worker’s report separate from the reviewer’s judgment?</li><li>Does a rejection create a traceable next action?</li><li>Do transitions retain their time, actor, source, and destination?</li><li>If the runtime crashes now, can it reconstruct what happened from disk?</li></ol><p>If most answers are “no,” adding more agents will usually increase ambiguity rather than throughput.</p><h2 id="what-everything-is-a-file-contributes-to-engineering" tabindex="-1">What “everything is a file” contributes to engineering <a class="header-anchor" href="#what-everything-is-a-file-contributes-to-engineering" aria-label="Permalink to &quot;What “everything is a file” contributes to engineering&quot;">​</a></h2><p>The point is not to replace databases, queues, and workflow engines with Markdown. It is to establish an open protocol surface with five engineering properties:</p><table tabindex="0"><thead><tr><th>Engineering property</th><th>How the ledger provides it</th></tr></thead><tbody><tr><td><strong>Addressable</strong></td><td>stable task identity, sender, recipient, and parent relationships</td></tr><tr><td><strong>Observable</strong></td><td>lifecycle buckets expose the current stage directly</td></tr><tr><td><strong>Replayable</strong></td><td><code>transitions:</code> preserves time, source, destination, actor, and tool</td></tr><tr><td><strong>Verifiable</strong></td><td>TASK, REPORT, ISSUE, and REVIEW can be checked against each other</td></tr><tr><td><strong>Composable and evolvable</strong></td><td>editors, Git, CLIs, and web views share the same artifacts, while stronger infrastructure can be added later</td></tr></tbody></table><blockquote><p><strong>Stable identity + path state + transition history + delivery evidence = a governable shared work ledger.</strong></p></blockquote><p>The ledger does not solve contention, transactions, authorization, retries, or scheduling by itself. It first answers more basic questions: was the work formally delegated, who owns it now, why was it rejected, and what evidence justified acceptance?</p><p>Starting with files is neither nostalgia nor a rejection of infrastructure. Its engineering value is to let humans, Agents, and tools share the same inspectable facts, then upgrade the execution plane in response to real pressure.</p><p>FCoP is not an industry standard or a final answer. It offers a testable starting point: <strong>before expanding the control plane, make the collaboration visible, machine-readable, and evidence-checkable.</strong></p><p>Once files provide the work ledger, the next question is how to implement transitions without exposing partial artifacts and how to test every invariant. Continue with <a href="/joinwell52/en/engineering/2026-08-18-fcop-file-state-machine">Files, Paths, and Events: Implementing and Testing the FCoP State Machine</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://pdos.csail.mit.edu/6.828/2014/readings/ritchie78unix.pdf" target="_blank" rel="noreferrer">Ritchie &amp; Thompson, The UNIX Time-Sharing System</a></li><li><a href="https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/537" target="_blank" rel="noreferrer">H. Penny Nii, The Blackboard Model of Problem Solving and the Evolution of Blackboard Architectures</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038: FCoP Boundary Charter</a></li></ul>`,65))])}const w=n(c,[["render",d]]);export{v as __pageData,w as default};
